import {DAYS,COUNTS,TOOLS,newGame,effectiveTroops,heroes,risk,current,where,inspect,act,endNight,nextDay} from './engine.mjs';
import {icon,portrait,castle} from './art.js';
import {TOPICS,changeTopic,upgradeDialogues} from './dialogue.mjs';
import {askQuestion} from './questions.mjs';
import {getEnding,beginEnding,endingStep,advanceEnding} from './endings.mjs';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const questionDrafts=new Map();let composingQuestion=false;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE='maou-border-v1';let state=null,screen='title',lastTool=null,sound=false,audioCtx=null,toastTimer;
function readSave(){try{const s=JSON.parse(localStorage.getItem(SAVE));return s&&s.version===1&&Number.isInteger(s.day)&&s.day>=1&&s.day<=8&&Array.isArray(s.queue)&&Array.isArray(s.held)&&Array.isArray(s.residents)?upgradeDialogues(s):null;}catch{return null;}}
let saveAvailable=!!readSave(),storageOK=true;
function save(){try{localStorage.setItem(SAVE,JSON.stringify(state));saveAvailable=true;}catch{storageOK=false;}}
function tone(type='click'){if(!sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const notes=type==='good'?[392,523,659]:type==='bad'?[196,155]:type==='night'?[220,261,330]:[420];notes.forEach((n,i)=>{const osc=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime+i*.09;osc.type='sine';osc.frequency.value=n;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.07,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+.35);osc.connect(g);g.connect(audioCtx.destination);osc.start(t);osc.stop(t+.4);});}catch{sound=false;}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function showModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="閉じる">${icon('close',18)}</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();}
function soundButton(){return `<button class="icon-btn" data-action="sound" aria-label="効果音を${sound?'オフ':'オン'}にする" title="効果音 ${sound?'ON':'OFF'}">${icon('sound',17)}${sound?'':'<span style="position:absolute;font-size:7px;margin-top:28px">OFF</span>'}</button>`;}
function renderTitle(){screen='title';app.innerHTML=`<main class="title-screen">${castle()}<div class="title-border"></div><div class="embers">${Array.from({length:18},(_,i)=>`<i style="left:${i*6}%;animation-delay:-${i*.7}s;animation-duration:${8+i%6}s"></i>`).join('')}</div><header class="title-top"><div class="title-brand">${icon('crown',23)}<span>OBSIDIAN KINGDOM</span></div><span class="small-label">魔王軍・国境管理局</span>${soundButton()}</header><div class="title-guards left">${portrait({id:100,look:0,name:'ゴブリンの旅人'})}</div><div class="title-guards right">${portrait({id:101,look:1,name:'角族の旅人'})}</div><div class="title-main"><div class="crest"><div class="crest-ring">${icon('crown',42)}</div></div><p class="title-kicker">そのハンコが、魔王の運命を変える。</p><h1 class="game-title"><span class="first">魔王軍にも</span><span class="main">入国審査が</span><span class="last">あるってこと！？</span></h1><div class="title-rule">◆</div><p class="title-tagline">ようこそ、魔王城の最前線へ。<br>見抜くべきは、書類の嘘か。旅人の正体か。</p><div class="title-actions">${saveAvailable?`<button class="btn primary" data-action="continue">${icon('book',21)} 記録から再開する ${icon('arrow',18)}</button><button class="btn secondary" data-action="new">新しく門番に着任する</button>`:`<button class="btn primary" data-action="new">${icon('gate',23)} 門番に着任する ${icon('arrow',18)}</button>`}<button class="btn secondary" data-action="help">${icon('book',17)} 門番の手引きを読む</button></div></div><footer class="title-bottom"><div class="features"><span>${icon('moon',16)} 全8日間の防衛</span><span>${icon('glass',16)} 8種類の検査道具</span><span>${icon('shield',16)} あなたの判断で変わる運命</span></div><span class="version">PROTOTYPE — v1.3</span></footer></main>`;}
function render(){if(screen==='title'){renderTitle();return;}if(state.phase!=='day'){if(state.ending&&getEnding(state))renderEnding();else renderNight();return;}renderGame();}
function renderGame(){const s=state,c=current(s),loc=c?where(s,c):null;const stat=(label,value,unit,ico,extra='')=>`<div class="stat ${extra}"><div class="label">${icon(ico,13)}${label}</div><div class="stat-value">${value}<small>${unit}</small></div>${ico==='shield'?`<div class="meter"><div style="width:${effectiveTroops(s)}%"></div></div>`:''}</div>`;
 app.innerHTML=`<main class="game-shell"><header class="game-header"><button class="wordmark" data-action="title" aria-label="タイトル画面へ"><span class="seal">${icon('crown',24)}</span><span><b>魔王軍・入国審査局</b><small>OBSIDIAN BORDER CONTROL</small></span></button><div class="header-controls"><span class="saved-indicator">${storageOK?'自動記録中':'保存不可・この画面で継続'}</span>${soundButton()}<button class="icon-btn" data-action="help" aria-label="遊び方">${icon('help',18)}</button></div></header><section class="stats" aria-label="城の状況">${stat('防衛日程',`${String(s.day).padStart(2,'0')}`,'/ 08 日','moon')}${stat('魔王軍の兵力',effectiveTroops(s),' / 100','shield')}${stat('備蓄食料',s.food,'日消費 4','food')}${stat('城内の勇者',heroes(s),'名','sword')}${stat('今夜の死亡確率',risk(s),'％ ※消耗前','crown','risk')}</section><section class="office-heading"><h1>黒曜城・正門検問所<span>THE BORDER OFFICE</span></h1><div class="day-progress" aria-label="${s.day}日目">${Array.from({length:DAYS},(_,i)=>`<span class="${i<s.day?'done':''}"></span>`).join('')}</div></section><div class="desk"><section class="workspace">${c?inspectionView(c,loc):`<div class="empty-desk">${icon('moon',53)}<span class="small-label">TODAY'S INSPECTION COMPLETE</span><h2>本日の来訪者は以上です</h2><p>隔離室と城内名簿を確認したら、夜の報告へ。<br>残った勇者と兵力によって、魔王様の運命が決まります。</p><div class="ornament">― ◆ ―</div><button class="btn primary" data-action="night">夜の報告を受ける ${icon('arrow',17)}</button></div>`}${c?`${questionView(c)}<div class="inspection-note" aria-live="polite">${evidenceView(c)}</div><div class="decision-label"><span>処遇を決定する</span><span>${loc==='queue'?`本日 ${s.processed+1} / ${COUNTS[s.day-1]} 名`:loc==='held'?'隔離中の来訪者':'入国済みの人物'}${loc!=='queue'?'　<button class="back-queue" data-action="queue">窓口に戻る</button>':''}</span></div><div class="decisions">${decision('admit','入国許可',loc==='resident'?'入国済み':'城内へ通す','check',loc==='resident')}${loc==='queue'?decision('deny','入国拒否','門前で帰す','close'):decision('expel','追放','兵力 −8 ／ 再訪あり','gate')}${decision('hold','一時隔離',`残り ${2-s.held.length} 枠`,'lock',loc!=='queue'||s.held.length>=2)}${decision('kill','殺害','兵力 −15 ／ 永久排除','sword',s.troops<15)}</div>`:''}<div class="desk-footer"><span>${icon('shield',14)} 魔王様を第8日の夜まで守り抜け。${s.held.length?`　隔離警備に ${s.held.length*3} 名配置中`:''}</span><button class="btn small ${s.queue.length?'ghost':'primary'}" data-action="night" ${s.queue.length?'disabled':''}>審査を終える ${icon('moon',14)}</button></div></section><aside class="sidebar"><section class="panel edict"><strong>${icon('book',17)} 本日の追加通達</strong><p>${TOOLS[s.day-1].lesson}</p><button data-action="rules">これまでの規則を確認 →</button></section><section class="panel tools-panel"><div class="panel-title"><span class="row">${icon('glass',16)} 検査道具</span><small>${s.day} / 8 解放</small></div><div class="tools">${TOOLS.map((t,i)=>i<s.day?`<button class="tool ${lastTool===i?'active':''}" data-action="inspect" data-tool="${i}" ${!c?'disabled':''} title="${t.desc}"><span class="tool-icon">${icon(t.icon,23)}</span><span><b>${t.name}</b><small>${t.short}</small></span>${c?.inspected[i]?`<span class="checkmark ${c.inspected[i].type}">✓</span>`:i===s.day-1?'<span class="new">NEW</span>':''}</button>`:`<button class="tool locked" disabled aria-label="${i+1}日目に${t.name}を支給"><span class="tool-icon">${icon('lock',15)}</span><span><b>${t.name}</b></span><small style="margin-left:auto">DAY ${i+1}</small></button>`).join('')}</div></section><section class="panel"><div class="panel-title"><span class="row">${icon('lock',15)} 隔離スペース</span><small>${s.held.length} / 2 名</small></div><div class="holding">${[0,1].map(i=>s.held[i]?`<button class="cell occupied" data-action="select" data-id="${s.held[i].id}" aria-label="${s.held[i].name}を再検査">${portrait(s.held[i],true)}<span class="cell-name">${s.held[i].name}</span></button>`:`<div class="cell">${icon('lock',18)}空き部屋 ${String(i+1).padStart(2,'0')}</div>`).join('')}</div><p class="holding-foot">1名につき警備兵3名を配置。再検査できます。</p></section><button class="roster-btn" data-action="roster"><span>${icon('person',15)} 城内の入国者名簿</span><span>${s.residents.length} 名 →</span></button></aside></div></main>`;
}
function decision(action,title,desc,ico,disabled=false){return `<button class="decision ${action==='expel'?'deny':action}" data-action="decision" data-decision="${action}" ${disabled?'disabled':''}>${icon(ico,22)}<b>${title}</b><small>${desc}</small></button>`;}
function inspectionView(c,loc){return `<div class="inspection"><div class="visitor-area"><span class="visitor-tag">${loc==='queue'?'来訪者の審査':loc==='held'?'隔離室で再検査':'城内で再検査'}</span><span class="visitor-number">No. ${String(c.id+1).padStart(3,'0')}</span>${portrait(c)}<div class="speech"><small>${c.speechTopic==='question'?'指さし回答（はい／いいえ）':c.language==='共通語'?'共通語':`${c.language}・翻訳が必要`}</small><span class="spoken-line">「${c.quote}」</span><div class="speech-questions" aria-label="来訪者への質問">${Object.entries(TOPICS).map(([key,label])=>`<button data-action="talk" data-topic="${key}" aria-pressed="${c.speechTopic===key}" class="${c.speechTopic===key?'selected':''}">${label}</button>`).join('')}</div></div><div class="visitor-plaque"><b>${c.name}</b><small>APPLICANT ${String(c.id+1).padStart(3,'0')}</small></div></div><div class="paper-area"><div class="paper-heading"><span>提出された書類</span><span>01 / 01</span></div><article class="passport"><div class="passport-top">${icon('crown',33)}<div><h2>入城許可証</h2><small>KINGDOM ENTRY PERMIT</small></div></div><div class="passport-person"><div><span>NAME / 氏名</span><h3>${c.name}</h3></div><div class="passport-photo">${portrait(c,true)}</div></div><dl><dt>種族</dt><dd>${c.species}</dd><dt>職業・目的</dt><dd>${c.job}</dd><dt>入城先</dt><dd>${c.destination}</dd><dt>許可番号</dt><dd>${c.permit}</dd><dt>申告魔力</dt><dd>${c.magic} mp</dd><dt>添付書類</dt><dd>${c.invitation?'王印つき招待状':c.job==='王室鍛冶師'?'王室修理許可証':'なし'}</dd></dl><div class="stamp"><div class="stamp-note">黒曜城 国境管理局 発行<br>書類の偽造は厳しく罰せられる。</div><div class="stamp-seal">${icon('moon',19)}<span>魔王軍公認</span></div></div></article><p class="document-hint">右の道具で、書類と本人を調べましょう。</p></div></div>`;}
function questionView(c){const history=c.questions||[],last=history.at(-1);return `<section class="question-panel" aria-label="文章で質問"><div class="row spread"><label for="free-question">${icon('help',16)} 文章で質問する</label><small>指さしで「はい」「いいえ」</small></div><form id="question-form"><div class="question-input-row"><input id="free-question" name="question" type="text" maxlength="120" autocomplete="off" value="${esc(questionDrafts.get(c.id)||'')}" placeholder="例：薬草を持っていますか？" aria-describedby="question-hint question-error"><button class="btn primary" type="submit">質問する ${icon('arrow',15)}</button></div><p id="question-error" class="question-error" role="alert"></p></form><p id="question-hint">種族・職業・荷物・書類について、一つずつ質問できます。</p><div class="question-examples">${['招待状はありますか？','あなたは人間ですか？','武器を持っていますか？'].map(q=>`<button type="button" data-action="question-example" data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div>${last?`<div class="question-answer" aria-live="polite"><div><small>あなたの質問</small><p>${esc(last.question)}</p><small>確認した内容：${esc(last.meaning)}</small></div><strong>${esc(last.answer)}</strong></div>`:''}<p class="question-caution">回答は本人の自己申告です。書類や検査結果と照らし合わせましょう。</p>${history.length>1?`<details class="question-history"><summary>この人物への質問履歴（${history.length}件）</summary>${history.slice(0,-1).reverse().map(q=>`<div><span>${esc(q.question)}</span><b>${esc(q.answer)}</b></div>`).join('')}</details>`:''}</section>`;}
function submitQuestion(event){if(event.target.id!=='question-form')return;event.preventDefault();if(composingQuestion||screen!=='game'||state?.phase!=='day')return;const c=current(state);if(!c)return;const input=document.querySelector('#free-question'),result=askQuestion(c,input.value);if(result.error){document.querySelector('#question-error').textContent=result.error;input.setAttribute('aria-invalid','true');return;}questionDrafts.delete(c.id);for(const i of [2,6])if(c.inspected[i]&&i<state.day)inspect(state,c,i);lastTool=c.inspected[6]?6:c.inspected[2]?2:null;save();render();tone();}
document.addEventListener('submit',submitQuestion);
document.addEventListener('input',event=>{if(event.target.id==='free-question'&&state){questionDrafts.set(current(state).id,event.target.value);event.target.removeAttribute('aria-invalid');document.querySelector('#question-error').textContent='';}});
document.addEventListener('compositionstart',event=>{if(event.target.id==='free-question')composingQuestion=true;});
document.addEventListener('compositionend',event=>{if(event.target.id==='free-question')composingQuestion=false;});
document.addEventListener('keydown',event=>{if(event.target.id==='free-question'&&event.key==='Enter'&&(event.isComposing||composingQuestion||event.keyCode===229))event.preventDefault();});
function evidenceView(c){let e=lastTool!==null?c.inspected[lastTool]:null;if(!e){const entries=Object.values(c.inspected);e=entries.at(-1);}return e?`<div class="row"><span class="${e.type}">${icon(e.type==='bad'?'close':e.type==='warn'?'help':'check',18)}</span><div><b class="${e.type}">${e.title}</b><p>${e.text}</p></div></div><div class="evidence-list">${Object.entries(c.inspected).map(([i,r])=>`<span class="${r.type}">${TOOLS[i].short} ${r.type==='bad'?'不一致':r.type==='warn'?'要確認':'確認済'}</span>`).join('')}</div>`:`<div class="empty">${icon('glass',25)}<div>まだ検査していません。<br><span style="font-size:10px">道具を選ぶと、ここに検査結果が表示されます。</span></div></div>`;}
function help(){showModal('門番の手引き',`<div class="tutorial-steps">${[['見比べる','1日3〜5名が来訪。通達を読み、書類・言葉・荷物を検査します。毎日、新しい道具が1つ支給されます。吹き出しの質問ボタンに加え、文章でも質問できます。回答は指さしで「はい」「いいえ」。自己申告には嘘が混じるため、道具と照合しましょう。'],['判断する','入国許可・入国拒否・隔離を選択。隔離は2名まで。翌日、新しい道具で再検査できます。'],['城を守る','城内名簿から入国者を再検査し、追放（兵力−8）または殺害（−15）できます。追放した勇者は再訪する場合があります。'],['8日間を生き残る','城内の勇者が3名以上になると、夜に魔王様の死亡判定が発生。兵力の消耗は死亡率を上げます。']].map((a,i)=>`<div class="tutorial-step"><span class="step-num">0${i+1}</span><div><b>${a[0]}</b><p>${a[1]}</p></div></div>`).join('')}</div><h3>味方の入国も必要です</h3><p>補給商人は食料＋5、他の味方は＋2。衛兵は兵力＋12、回復術師は＋8も補充します。毎晩食料を4消費し、不足すると兵力−18。兵力が0になると防衛線が崩壊します。</p><h3>夜の危険度</h3><p>勇者0〜2名：0％ ／ 3名：20％ ／ 4名：35％ ／ 5名：55％ ／ 6名以上：75％。兵力が10減るごとに＋5ポイント（最大95％）。毎晩、勇者1名につき兵力3を失ってから判定します。隔離中の勇者は侵入者数に含みません。</p><div class="modal-actions"><button class="btn primary" data-action="close">了解。魔王様を守ろう ${icon('shield',17)}</button></div>`);}
function rules(){showModal('魔王軍・入城審査規則',`<p>一つでも規則違反があれば入国を拒否できます。怪しい外見だけで判断せず、例外の許可証も確認しましょう。</p>${TOOLS.slice(0,state.day).map((t,i)=>`<div class="rule-entry"><b>第${i+1}日 ／ ${t.name}</b>${t.lesson}</div>`).join('')}<div class="modal-actions"><button class="btn primary" data-action="close">審査へ戻る</button></div>`);}
function unlock(){const t=TOOLS[state.day-1];showModal(`第${state.day}日・新しい道具の支給`,`<div class="unlock-card">${icon(t.icon,49)}<p class="small-label">NEW INSPECTION TOOL</p><h3>${t.name}</h3><p>${t.desc}</p></div><h3>本日の追加通達</h3><p>${t.lesson}</p><p style="margin-top:13px">本日の来訪者は${COUNTS[state.day-1]}名です。${state.held.length?'昨日の隔離者も新しい道具で調べられます。':'魔王様のご無事を祈ります。'}</p><div class="modal-actions"><button class="btn primary" data-action="close">審査を始める ${icon('arrow',17)}</button></div>`);}
function roster(){showModal('城内の入国者名簿',`<p style="margin-bottom:15px">人物を選んで再検査できます。追放と殺害には兵力を消費します。</p><div class="roster-list">${state.residents.length?state.residents.map(c=>`<button class="roster-card" data-action="select" data-id="${c.id}">${portrait(c,true)}<span><b>${c.name}</b><small>${c.species} ／ ${c.job}</small></span><span class="btn small">再検査 →</span></button>`).join(''):'<p class="muted">入国済みの人物はまだいません。</p>'}</div>`);}
function confirmDecision(action){const c=current(state);if(!c)return;if(action==='kill'||action==='expel'){const cost=action==='kill'?15:8;showModal(action==='kill'?'殺害命令を出しますか？':'城外へ追放しますか？',`<p><strong>${c.name}</strong>に対して、${action==='kill'?'殺害':'追放'}命令を出します。</p><div class="cost-box">魔王軍の兵力：${state.troops} → <b>${Math.max(0,state.troops-cost)}</b><br>${action==='kill'?'対象は永久に排除されます。味方だった場合も取り消せません。':'対象は城外に移されます。勇者だった場合、後日変装して再訪することがあります。'}<br>兵力の低下は、勇者3名以上のときの魔王様の死亡率を高めます。</div><div class="modal-actions"><button class="btn ghost" data-action="close">戻る</button><button class="btn danger" data-action="execute" data-decision="${action}" ${state.troops<cost?'disabled':''}>${action==='kill'?'殺害命令を実行':'追放を実行'}（兵力 −${cost}）</button></div>`);}else execute(action);}
function execute(action){closeModal();const r=act(state,action);if(r.error){toast(r.error);return;}lastTool=null;save();render();tone(action==='admit'?'good':action==='kill'?'bad':'click');toast(`${r.name}：${r.action}${r.cost?` ／ 兵力 −${r.cost}`:''}`);}
function renderNight(){const n=state.night,won=state.phase==='won',lost=state.phase==='lost';const title=won?'魔王様を守り抜いた！':lost?'黒曜城、陥落。':'魔王様は、ご無事です。';app.innerHTML=`<main class="night-shell">${castle()}<article class="report"><p class="small-label">${won?'MISSION COMPLETE':lost?'MISSION FAILED':`NIGHT REPORT — DAY ${String(state.day).padStart(2,'0')}`}</p><div class="report-symbol ${lost?'bad':''}">${icon(lost?'sword':won?'crown':'moon',51)}</div><h1>${title}</h1><p class="sub">${won?'8日間の任務を完遂。あなたの判断が、魔王軍の明日を守りました。':lost?(state.troops===0?'兵力が尽き、防衛線は崩壊。魔王様を守り切れませんでした。':'城内に潜んだ勇者たちが玉座に到達。魔王様は討たれてしまいました。'):'静かな夜の向こうに、また新しい来訪者たちが待っています。'}</p><div class="report-stats"><div><b>${n.heroes}<small> 名</small></b><small>城内に残る勇者</small></div><div><b>${effectiveTroops(state)}<small> / 100</small></b><small>残存兵力</small></div><div><b>${n.chance}<small> ％</small></b><small>今夜の死亡確率</small></div></div><div class="report-events"><p>${n.heroes?`城内の勇者${n.heroes}名との戦闘で、魔王軍の兵力が${n.heroes*3}減少。`:'今夜、城内に勇者の侵入は確認されませんでした。'}</p>${n.starvation?'<p class="bad">食料が不足。補給線が途絶え、兵力をさらに18失いました。</p>':`<p>食料を4消費。残りの備蓄は${state.food}です。</p>`}${n.events.filter(e=>e.hero&&e.action==='入国許可').map(e=>`<p class="bad">諜報部より：本日通した「${e.name}」は勇者でした。</p>`).join('')}${n.events.filter(e=>e.action==='殺害'||e.action==='追放').map(e=>`<p>「${e.name}」を${e.action}。正体は${e.hero?'勇者':'魔王軍の味方'}でした。作戦で兵力${e.cost}を消耗。</p>`).join('')}${state.held.length?`<p>隔離室に${state.held.length}名を収容中。警備兵${state.held.length*3}名は防衛兵力から一時離脱。</p>`:''}</div>${won||lost?`<button class="btn primary" data-action="ending">${icon('book',18)} ${won?'その後の物語へ':'結末を読む'} ${icon('arrow',17)}</button><button class="btn ghost" data-action="restart">${won?'もう一度、魔王様を守る':'もう一度、門番に挑戦する'} ${icon('arrow',17)}</button><button class="btn ghost" data-action="title">タイトルへ戻る</button>`:`<button class="btn primary" data-action="next">第${state.day+1}日へ進む ${icon('arrow',17)}</button>`}<p class="report-roll">${n.chance>0?`運命の判定：${n.roll} / 100　（${n.chance}以下で陥落）`:'勇者が3名未満のため、暗殺の判定は発生しません。'}</p></article></main>`;}
function renderEnding(){
 const e=getEnding(state),step=endingStep(state),result=step===3;
 const figure=e.tone==='ash'?{id:203,look:43,name:'最後の伝令'}:{id:201,look:41,name:'魔王様'};
 const metrics=[['到達日',`${e.stats.day} / 8`],['審査した来訪者',`${e.stats.visitors} 名`],['残存兵力',`${e.stats.troops} / 100`],['兵力の累計損失',`${e.stats.losses}`],['迎えた味方',`${e.stats.alliesAdmitted} 名`],['勇者の入国許可',`${e.stats.heroesAdmitted} 回`],['勇者の入国拒否',`${e.stats.heroesDenied} 回`],['味方の拒否・追放',`${e.stats.alliesTurnedAway} 回`],['味方の殺害',`${e.stats.alliesKilled} 名`]];
 app.innerHTML=`<main class="ending-screen ${e.tone}">${castle()}<header class="ending-top"><span class="small-label">OBSIDIAN KINGDOM · EPILOGUE</span><div class="row">${soundButton()}<button class="btn small ghost" data-action="title">タイトルへ</button></div></header><section class="ending-frame ${result?'ending-result':''}"><div class="ending-overline"><span>ENDING ${e.number}</span><span>${state.phase==='won'?'任務完遂':'任務終了'}</span></div><h1>${e.title}</h1><p class="ending-subtitle">${e.subtitle}</p>${result?`<div class="ending-award">${icon('crown',36)}<span>${e.seal}</span></div><div class="ending-metrics">${metrics.map(([label,value])=>`<div><small>${label}</small><strong>${value}</strong></div>`).join('')}</div><p class="ending-footnote">城内に残る勇者：${e.stats.remainingHeroes}名 ／ 隔離中：${e.stats.held}名<br>追放・再訪があるため、入国許可や拒否は回数で集計しています。</p><div class="ending-thanks"><p>魔王軍にも入国審査があるってこと！？</p><span>あなたの判断が、この物語の結末になりました。</span></div><div class="ending-controls"><button class="btn ghost" data-action="ending">物語を読み返す</button><button class="btn primary" data-action="restart">新しい任務を始める ${icon('arrow',17)}</button></div>`:`<div class="ending-story"><div class="ending-visual">${step===1?`<div class="ending-character">${portrait(figure)}${e.tone!=='ash'?`<span class="ending-crown">${icon('crown',55)}</span>`:''}</div><span class="ending-visual-caption">${e.scenes[step].speaker}</span>`:`<div class="ending-sigil">${icon(step===0?'gate':e.tone==='ash'?'book':'shield',90)}</div><div class="ending-orbit"></div><span class="ending-visual-caption">${step===0?'黒曜城':'門番の記録'}</span>`}</div><div class="ending-prose" aria-live="polite"><p class="ending-place">${e.scenes[step].place}</p><h2>${e.scenes[step].speaker}</h2><p class="ending-text">${e.scenes[step].text}</p><div class="ending-pages" aria-label="物語 ${step+1} / 3">${[0,1,2].map(i=>`<span class="${i===step?'active':''}"></span>`).join('')}</div></div></div><div class="ending-controls"><button class="btn ghost" data-action="ending-back" ${step===0?'disabled':''}>前の場面</button><button class="btn primary" data-action="ending-next">${step===2?'最終戦績を見る':'物語を進める'} ${icon('arrow',17)}</button></div><button class="ending-skip" data-action="ending-skip">物語をスキップして戦績へ</button>`}</section><footer class="ending-bottom">― あなたが守ったものを、忘れない。 ―</footer></main>`;
}
function start(){state=newGame();lastTool=null;screen='game';save();render();unlock();tone('good');}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;switch(action){case 'new':if(saveAvailable){showModal('新しい任務を始めますか？','<p>現在の記録を上書きして、第1日から始めます。</p><div class="modal-actions"><button class="btn ghost" data-action="close">戻る</button><button class="btn primary" data-action="restart">新しい任務を始める</button></div>');}else start();break;case 'restart':closeModal();start();break;case 'continue':state=readSave();if(!state){saveAvailable=false;toast('保存記録を読み込めませんでした。');renderTitle();break;}screen='game';render();tone();break;case 'title':closeModal();if(state)save();renderTitle();break;case 'sound':sound=!sound;tone('good');render();break;case 'help':help();break;case 'rules':rules();break;case 'close':closeModal();break;case 'inspect':{const c=current(state);if(!c)break;lastTool=Number(b.dataset.tool);const r=inspect(state,c,lastTool);save();render();tone(r.type==='bad'?'bad':'click');break;}case 'talk':{const c=current(state);if(!c||!changeTopic(c,b.dataset.topic))break;for(const i of [2,6])if(c.inspected[i]&&i<state.day)inspect(state,c,i);lastTool=c.inspected[6]?6:c.inspected[2]?2:null;save();render();tone();break;}case 'question-example':{const input=document.querySelector('#free-question');if(input){input.value=b.dataset.question;questionDrafts.set(current(state).id,input.value);input.focus();}break;}case 'decision':confirmDecision(b.dataset.decision);break;case 'execute':execute(b.dataset.decision);break;case 'select':state.selected=Number(b.dataset.id);lastTool=null;closeModal();save();render();window.scrollTo({top:0,behavior:'smooth'});break;case 'queue':state.selected=null;lastTool=null;save();render();break;case 'roster':roster();break;case 'night':{if(state.queue.length){toast('本日の来訪者を全員審査してください。');break;}showModal('夜の報告へ進みますか？',`<p>勇者${heroes(state)}名が城内に残っています。今夜は戦闘で兵力${heroes(state)*3}を消耗${state.food<4?'し、食料不足でさらに18減少':''}してから、生存判定を行います。${state.held.length?`隔離中の${state.held.length}名は翌日も収容されます。`:''}</p><div class="modal-actions"><button class="btn ghost" data-action="close">まだ確認する</button><button class="btn primary" data-action="end-night">夜の報告を受ける ${icon('moon',17)}</button></div>`);break;}case 'end-night':closeModal();endNight(state);save();render();window.scrollTo(0,0);tone(state.phase==='lost'?'bad':'night');break;case 'ending':if(beginEnding(state)){save();render();window.scrollTo(0,0);tone('night');}break;case 'ending-next':case 'ending-skip':if(advanceEnding(state,action==='ending-skip')){save();render();window.scrollTo(0,0);tone();}break;case 'ending-back':if(state.ending){state.ending.step=Math.max(0,endingStep(state)-1);save();render();window.scrollTo(0,0);}break;case 'next':nextDay(state);lastTool=null;save();render();window.scrollTo(0,0);unlock();tone('good');break;}});
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable="true"]')||e.isComposing)return;if(screen==='game'&&state?.phase==='day'&&!modal.open&&/^[1-8]$/.test(e.key)){const i=Number(e.key)-1;if(i<state.day&&current(state)){lastTool=i;inspect(state,current(state),i);save();render();tone();}}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
renderTitle();
